}

abstract final class RadiusTokens {
  /// Small parts inside a control: badges, checkboxes.
  static const double sm = 6;
  /// Controls: buttons, fields.
  static const double md = 10;
  /// Containers: cards, dialogs.
  static const double lg = 16;
  /// Surfaces that float free of the screen edges: sheets, floating bars.
  static const double xl = 24;
  /// Pills and circles.
  static const double full = 9999;
}

abstract final class BorderTokens {
  static const double widthThin = 1;
  /// Selected and invalid states that must not rely on color alone.
  static const double widthThick = 2;
}

abstract final class FocusTokens {
  /// Focus ring thickness. WCAG 2.2 asks for an indicator at least 2px thick.
  static const double width = 2;
  /// Gap between a control and its focus ring, so the ring reads against the control's own fill.
  static const double offset = 2;
}

abstract final class FontTokens {
  /// Pretendard covers Hangul, Latin and Kana with matching metrics. Where it is not loaded, Latin text falls to the system's own font and Hangul to the system's Korean font, in that order.
  static const List<String> familySans = ["Pretendard Variable", "Pretendard", "-apple-system", "BlinkMacSystemFont", "system-ui", "Roboto", "Helvetica Neue", "Segoe UI", "Apple SD Gothic Neo", "Noto Sans KR", "Malgun Gothic", "sans-serif"];
  /// The smallest size Hangul stays legible at.
  static const double sizeXs = 12;
  static const double sizeSm = 14;
  /// Body text. Also the size below which iOS zooms the page when a field is focused.
  static const double sizeMd = 16;
  static const double sizeLg = 18;
  static const double sizeXl = 22;
  static const double size2xl = 28;
  static const FontWeight weightRegular = FontWeight(400);
  /// Labels on controls: heavier than body text without shouting.
  static const FontWeight weightMedium = FontWeight(500);
  static const FontWeight weightSemibold = FontWeight(600);
  static const FontWeight weightBold = FontWeight(700);
  /// Large type and single-line labels.
  static const double lineHeightTight = 1.25;
  /// Headings and short text that may wrap.
  static const double lineHeightSnug = 1.4;
  /// Body text. Hangul needs more leading than Latin at the same size.
  static const double lineHeightNormal = 1.5;
}

abstract final class TypographyTokens {
  /// One per screen at most: the name of the place.
  static const TextStyle display = TextStyle(fontSize: 28, height: 35 / 28, fontWeight: FontWeight(700), letterSpacing: -0.3, leadingDistribution: TextLeadingDistribution.even);
  /// Section and dialog titles.
  static const TextStyle title = TextStyle(fontSize: 22, height: 28 / 22, fontWeight: FontWeight(700), letterSpacing: -0.2, leadingDistribution: TextLeadingDistribution.even);
  /// Card titles and group headings.
  static const TextStyle heading = TextStyle(fontSize: 18, height: 25 / 18, fontWeight: FontWeight(600), letterSpacing: 0, leadingDistribution: TextLeadingDistribution.even);
  /// Running text.
  static const TextStyle body = TextStyle(fontSize: 16, height: 24 / 16, fontWeight: FontWeight(400), letterSpacing: 0, leadingDistribution: TextLeadingDistribution.even);
  /// Emphasis inside running text.
  static const TextStyle bodyStrong = TextStyle(fontSize: 16, height: 24 / 16, fontWeight: FontWeight(600), letterSpacing: 0, leadingDistribution: TextLeadingDistribution.even);
  /// Button labels and field labels.
  static const TextStyle label = TextStyle(fontSize: 14, height: 20 / 14, fontWeight: FontWeight(500), letterSpacing: 0, leadingDistribution: TextLeadingDistribution.even);
  /// Descriptions, hints and secondary lines.
  static const TextStyle detail = TextStyle(fontSize: 14, height: 21 / 14, fontWeight: FontWeight(400), letterSpacing: 0, leadingDistribution: TextLeadingDistribution.even);
  /// Badges and timestamps.
  static const TextStyle footnote = TextStyle(fontSize: 12, height: 17 / 12, fontWeight: FontWeight(500), letterSpacing: 0, leadingDistribution: TextLeadingDistribution.even);
}

abstract final class MotionTokens {
  /// Feedback to a press or hover: must feel instant.
  static const Duration durationFast = Duration(milliseconds: 120);
  /// Something appearing or changing place.
  static const Duration durationNormal = Duration(milliseconds: 200);
  /// Large surfaces: sheets, full panels.
  static const Duration durationSlow = Duration(milliseconds: 320);
  /// One beat of a loading placeholder: slow enough not to nag.
  static const Duration durationPulse = Duration(milliseconds: 1200);
  /// How long the pointer rests on a control before its tooltip shows.
  static const Duration durationTooltipDelay = Duration(milliseconds: 500);
  /// How long a toast stays before it leaves on its own.
  static const Duration durationToast = Duration(milliseconds: 5000);
  /// Moving between two places on screen.
  static const Cubic easingStandard = Cubic(0.2, 0, 0, 1);
  /// Arriving: starts fast, settles.
  static const Cubic easingEnter = Cubic(0, 0, 0, 1);
  /// Leaving: starts slow, gets out of the way.
  static const Cubic easingExit = Cubic(0.3, 0, 1, 1);
  /// How far a button shrinks while it is pressed. Feedback that does not depend on color.
  static const double pressScale = 0.97;
  static const double springDefaultStiffness = 700;
  static const double springDefaultDamping = 0.9;
  static const double springFastStiffness = 1400;
  static const double springFastDamping = 0.9;
}

abstract final class ShadowTokens {
  /// Cards and outlined controls: just enough to lift them off the page. Drawn together with a hairline border.
  static const ShadowToken subtle = ShadowToken(color: Color(0x0F000000), offsetX: 0, offsetY: 1, blur: 2, spread: 0);
